{
  "manifest_version": 3,
  "name": "Aux Browsing Agent",
  "version": "1.26.1016.1890",
  "version_name": "1.26.1016.1852",
  "description": "Browsing agent for Aux browser",
  "key": "",
  "icons": {
    "16": "icons/icon-16.png",
    "48": "icons/icon-48.png",
    "128": "icons/icon-128.png"
  },
  "action": {
    "default_title": "Aux Browsing Agent"
  },
  "side_panel": {
    "default_path": "sidepanel.html"
  },
  "chrome_url_overrides": {
    "newtab": "newtab.html"
  },
  "permissions": [
    "sidePanel",
    "contextMenus",
    "storage",
    "activeTab",
    "tabCapture",
    "offscreen",
    "debugger",
    "downloads",
    "favicon",
    "history",
    "bookmarks",
    "topSites",
    "browsingData",
    "privacy",
    "management",
    "nativeMessaging",
    "cookies",
    "tabs",
    "scripting",
    "userScripts",
    "webNavigation",
    "sessions",
    "tabGroups",
    "alarms",
    "notifications",
    "dev.aux.blink.expose-wv",
    "dev.aux.ext.private.account",
    "dev.aux.ext.private.adblock",
    "dev.aux.ext.private.browserImport",
    "dev.aux.ext.private.notification",
    "dev.aux.ext.private.omnibox",
    "dev.aux.ext.private.browserPreferences",
    "dev.aux.ext.private.miniPopup",
    "dev.aux.ext.private.capture-tab-without-userinteraction",
    "dev.aux.ext.private.launch-extension"
  ],
  "host_permissions": [
    "<all_urls>",
    "https://api.anthropic.com/*"
  ],
  "web_accessible_resources": [
    {
      "resources": [
        "iframe.html",
        "tab-preview-player.html",
        "tabsearch.html",
        "react-grab-bridge.js",
        "assets/*"
      ],
      "matches": [
        "<all_urls>"
      ]
    }
  ],
  "commands": {
    "_execute_action": {
      "suggested_key": {
        "default": "Alt+Shift+B",
        "mac": "Alt+Shift+B"
      },
      "description": "Open Aux sidepanel"
    }
  },
  "externally_connectable": {
    "ids": []
  },
  "sandbox": {
    "pages": [
      "visual-frame.html"
    ]
  },
  "content_security_policy": {
    "sandbox": "sandbox allow-scripts allow-forms allow-popups allow-modals; script-src 'self' 'unsafe-inline' 'unsafe-eval' https:; child-src 'self';",
    "extension_pages": "script-src 'self'; object-src 'self'"
  },
  "background": {
    "service_worker": "background.js",
    "type": "module"
  },
  "content_scripts": [
    {
      "matches": [
        "<all_urls>"
      ],
      "js": [
        "content/content.js"
      ],
      "run_at": "document_idle"
    },
    {
      "matches": [
        "https://docs.google.com/document/*"
      ],
      "js": [
        "content/google-docs-selection-bridge.js"
      ],
      "run_at": "document_idle",
      "world": "MAIN"
    }
  ]
}
